// TeamsCanvas (#3335) — the org-chart canvas surface: agent/resource/external position nodes joined
// by relationship edges, with click-select and single-node drag. Promoted from harvested (it was
// already complete and tested) into base-studio-code, refactored to use the real Box/Row/Text/Chip
// primitives and the promoted AgentFace component instead of local raw-div redeclarations. Every
// interaction (drag gesture, edge click, hue-based archetype coloring) and all three node-kind
// renderings are unchanged from the vendored source.
import { useRef, useState } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Text } from "@/shared/ui/typography/Text";
import { AgentFace } from "@/components/teams-agent-face";

function hueColor(hue: number, chroma = 0.13, light = 0.72): string {
  return `oklch(${light} ${chroma} ${hue})`;
}
function styleDash(style?: "solid" | "dashed" | "dotted"): string | undefined {
  return style === "dashed" ? "5 4" : style === "dotted" ? "2 3" : undefined;
}
const NODE_W = 210, NODE_H = 84;
function nodeBox(pos: Position): { x: number; y: number; w: number; h: number } {
  return { x: pos.x, y: pos.y, w: NODE_W, h: NODE_H };
}
function edgeGeometry(a: { x: number; y: number; w: number; h: number }, b: { x: number; y: number; w: number; h: number }, bow = 0): { d: string; lx: number; ly: number } {
  const ax = a.x + a.w / 2, ay = a.y + a.h / 2;
  const bx = b.x + b.w / 2, by = b.y + b.h / 2;
  const mx = (ax + bx) / 2, my = (ay + by) / 2;
  const dx = bx - ax, dy = by - ay;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len;
  const cx = mx + nx * bow, cy = my + ny * bow;
  const d = bow ? `M ${ax} ${ay} Q ${cx} ${cy} ${bx} ${by}` : `M ${ax} ${ay} L ${bx} ${by}`;
  return { d, lx: bow ? cx : mx, ly: bow ? cy : my };
}

function NodeSkeleton() {
  const shimmer = { background: "linear-gradient(90deg,var(--bg-elev) 0%,var(--bg-elev2) 50%,var(--bg-elev) 100%)", backgroundSize: "260px 100%", animation: "skeleton-shimmer 1.1s linear infinite" };
  return (
    <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "10px 12px", display: "flex", flexDirection: "column", gap: 8, borderRadius: 13, background: "var(--bg-elev)", border: "1px solid var(--border)" }}>
      <Row gap={9} align="start">
        <div aria-hidden style={{ width: 27, height: 27, borderRadius: 8, flex: "none", ...shimmer }} />
        <Box style={{ minWidth: 0, flex: 1, display: "flex", flexDirection: "column", gap: 6 }}>
          <div aria-hidden style={{ width: "60%", height: 12, borderRadius: 4, ...shimmer }} />
          <div aria-hidden style={{ width: "85%", height: 9, borderRadius: 4, ...shimmer }} />
        </Box>
      </Row>
    </Box>
  );
}

export interface Position { nodeId: string; kind: "agent" | "resource" | "external"; x: number; y: number; personaId?: string; label?: string }
export interface Relationship { id: string; from: string; to: string; archetype: string; bow?: number }
export interface Team { positions: Position[]; relationships: Relationship[] }
export interface Persona { id: string; name: string; role?: string; blurb?: string; glyph?: string }
export interface RelationshipArchetype { id: string; label: string; hue: number; style?: "solid" | "dashed" | "dotted"; bidirectional?: boolean }
export interface Selection { type: "node" | "edge"; id: string }
function positionDisplay(pos: Position, personas: Persona[]): { glyph: string; name: string; role?: string; blurb: string } {
  if (pos.kind === "agent") {
    const p = personas.find((pp) => pp.id === pos.personaId);
    return { glyph: p?.glyph ?? "◆", name: p?.name ?? pos.label ?? "Unassigned", role: p?.role, blurb: p?.blurb ?? "" };
  }
  return { glyph: pos.kind === "resource" ? "▤" : "○", name: pos.label ?? pos.kind, blurb: "" };
}

const DEMO_ARCHETYPES: RelationshipArchetype[] = [
  { id: "reports", label: "reports to", hue: 250, style: "solid" },
  { id: "partners", label: "partners with", hue: 150, style: "dashed", bidirectional: true },
];
const DEMO_TEAM: Team = {
  positions: [
    { nodeId: "n1", kind: "agent", x: 40, y: 40, personaId: "p1" },
    { nodeId: "n2", kind: "agent", x: 320, y: 40, personaId: "p2" },
    { nodeId: "n3", kind: "resource", x: 180, y: 210, label: "Design system repo" },
  ],
  relationships: [
    { id: "r1", from: "n1", to: "n2", archetype: "partners" },
    { id: "r2", from: "n2", to: "n3", archetype: "reports" },
  ],
};
const DEMO_PERSONAS: Persona[] = [
  { id: "p1", name: "builder-1", role: "engineer", blurb: "Implements features end to end." },
  { id: "p2", name: "reviewer-2", role: "reviewer", blurb: "Reviews PRs and enforces scope." },
];
const PLACEHOLDER_XY = [{ x: 40, y: 40 }, { x: 320, y: 40 }];
const DRAG_THRESHOLD = 4;

export function TeamsCanvas({
  org = DEMO_TEAM, personas = DEMO_PERSONAS, archetypes = DEMO_ARCHETYPES,
  sel = { type: "node", id: "" }, onSelectNode, onSelectEdge, onMoveNode, loading = false, error,
}: {
  org?: Team; personas?: Persona[]; archetypes?: RelationshipArchetype[]; sel?: Selection;
  onSelectNode?: (nodeId: string) => void; onSelectEdge?: (relId: string) => void; onMoveNode?: (nodeId: string, x: number, y: number) => void;
  loading?: boolean; error?: string | boolean;
}) {
  const [drag, setDrag] = useState<{ nodeId: string; x: number; y: number } | null>(null);
  const gesture = useRef<{ nodeId: string; sx: number; sy: number; bx: number; by: number; moved: boolean } | null>(null);

  if (error) {
    return (
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Text tone="danger" size={12}>{typeof error === "string" ? error : "Couldn't load the org chart."}</Text>
      </div>
    );
  }
  if (loading) {
    return (
      <>
        {PLACEHOLDER_XY.map((xy, i) => (
          <div key={i} style={{ position: "absolute", left: xy.x, top: xy.y, width: NODE_W, height: NODE_H }}><NodeSkeleton /></div>
        ))}
      </>
    );
  }
  if (org.positions.length === 0) {
    return (
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <Text tone="muted" size={12} style={{ fontStyle: "italic" }}>No org chart yet - add a position to get started.</Text>
      </div>
    );
  }

  const boxes = new Map(org.positions.map((p) => [p.nodeId, nodeBox(p)]));

  const at = (nodeId: string) => (drag?.nodeId === nodeId ? drag : boxes.get(nodeId)!);
  const liveBox = (nodeId: string) => ({ ...boxes.get(nodeId)!, ...at(nodeId) });
  const edgeClick = (relId: string) => (e: any) => { e.stopPropagation(); onSelectEdge?.(relId); };

  const focused = !(sel.type === "node" && sel.id === "");
  const nodeActive = (id: string): boolean => {
    if (sel.type === "node") return id === sel.id;
    const e = org.relationships.find((r) => r.id === sel.id);
    return !!e && (e.from === id || e.to === id);
  };
  const edgeActive = (from: string, to: string): boolean =>
    sel.type === "edge" ? false : from === sel.id || to === sel.id;

  const onNodeDown = (nodeId: string) => (e: any) => {
    e.stopPropagation();
    const b = boxes.get(nodeId)!;
    gesture.current = { nodeId, sx: e.clientX, sy: e.clientY, bx: b.x, by: b.y, moved: false };
    e.currentTarget.setPointerCapture?.(e.pointerId);
  };
  const onNodeMove = (e: any) => {
    const g = gesture.current;
    if (!g) return;
    if (!g.moved && Math.hypot(e.clientX - g.sx, e.clientY - g.sy) < DRAG_THRESHOLD) return;
    g.moved = true;
    setDrag({ nodeId: g.nodeId, x: Math.round(g.bx + (e.clientX - g.sx)), y: Math.round(g.by + (e.clientY - g.sy)) });
  };
  const onNodeUp = (nodeId: string) => (e: any) => {
    const g = gesture.current;
    gesture.current = null;
    setDrag(null);
    e.currentTarget.releasePointerCapture?.(e.pointerId);
    if (g && g.moved) onMoveNode?.(nodeId, Math.round(g.bx + (e.clientX - g.sx)), Math.round(g.by + (e.clientY - g.sy)));
    else onSelectNode?.(nodeId);
  };

  const archetypeById = (id: string) => archetypes.find((a) => a.id === id);

  return (
    <>
      <svg style={{ position: "absolute", left: 0, top: 0, width: "100%", height: "100%", overflow: "visible", pointerEvents: "none" }}>
        <defs>
          <marker id="org-ah" markerWidth={10} markerHeight={10} refX={7} refY={3.4} orient="auto" markerUnits="userSpaceOnUse">
            <path d="M0,0 L7.5,3.4 L0,6.8 Z" fill="context-stroke" />
          </marker>
        </defs>
        {org.relationships.map((r) => {
          const arch = archetypeById(r.archetype);
          if (!arch || !boxes.get(r.from) || !boxes.get(r.to)) return null;
          const { d } = edgeGeometry(liveBox(r.from), liveBox(r.to), r.bow ?? 0);
          const act = edgeActive(r.from, r.to);
          const isSelEdge = sel.type === "edge" && r.id === sel.id;
          const color = hueColor(arch.hue);
          return (
            <g key={r.id}>
              <path d={d} fill="none" stroke="transparent" strokeWidth={18} style={{ cursor: "pointer", pointerEvents: "stroke" }} onClick={edgeClick(r.id)} />
              <path d={d} fill="none" stroke={color} strokeWidth={isSelEdge ? 2.8 : act ? 2 : 1.7}
                strokeDasharray={styleDash(arch.style)} strokeLinecap="round"
                markerEnd="url(#org-ah)" markerStart={arch.bidirectional ? "url(#org-ah)" : undefined}
                opacity={!focused ? 1 : (isSelEdge || act ? 1 : 0.26)} style={{ transition: "opacity .15s" }} />
            </g>
          );
        })}
      </svg>
      <Box style={{ position: "absolute", inset: 0, pointerEvents: "none" }}>
        {org.relationships.map((r) => {
          const arch = archetypeById(r.archetype);
          if (!arch || !boxes.get(r.from) || !boxes.get(r.to)) return null;
          const { lx, ly } = edgeGeometry(liveBox(r.from), liveBox(r.to), r.bow ?? 0);
          const act = edgeActive(r.from, r.to);
          const isSelEdge = sel.type === "edge" && r.id === sel.id;
          const color = hueColor(arch.hue);
          return (
            <Box key={r.id} onClick={edgeClick(r.id)}
              style={{ position: "absolute", left: lx, top: ly, transform: "translate(-50%,-50%)",
                display: "inline-flex", alignItems: "center", gap: 5, padding: "2.5px 8px", borderRadius: 999,
                background: "var(--bg-elev)", border: `1px solid ${color}`, color: "var(--fg)", fontSize: 10, fontWeight: 600,
                whiteSpace: "nowrap", pointerEvents: "auto", cursor: "pointer", opacity: !focused ? 1 : (isSelEdge || act ? 1 : 0.32), transition: "opacity .15s" }}>
              <Box style={{ width: 6, height: 6, borderRadius: "50%", background: color, flex: "none" }} />
              {arch.label}
            </Box>
          );
        })}
      </Box>
      {org.positions.map((pos) => {
        const xy = at(pos.nodeId);
        const box = boxes.get(pos.nodeId)!;
        const d = positionDisplay(pos, personas);
        const isSel = sel.type === "node" && sel.id === pos.nodeId;
        const dim = focused && !nodeActive(pos.nodeId);
        return (
          <div key={pos.nodeId}
            onPointerDown={onNodeDown(pos.nodeId)} onPointerMove={onNodeMove} onPointerUp={onNodeUp(pos.nodeId)}
            style={{ position: "absolute", left: xy.x, top: xy.y, width: box.w, height: box.h,
              cursor: "grab", zIndex: isSel ? 6 : 3, opacity: dim ? 0.5 : 1, transition: drag ? "none" : "opacity .15s", touchAction: "none", userSelect: "none" }}>
            {pos.kind === "agent" && <AgentFace d={d} isSel={isSel} />}
            {pos.kind === "resource" && (
              <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "11px 13px", display: "flex", flexDirection: "column", justifyContent: "center",
                clipPath: "polygon(12% 0,88% 0,100% 50%,88% 100%,12% 100%,0 50%)",
                background: isSel ? hueColor(340, 0.5, 0.09) : "color-mix(in oklch, var(--fg) 4%, transparent)",
                border: `1px solid ${isSel ? hueColor(340) : "var(--border)"}` }}>
                <Text as="span" size={9} tone="muted" style={{ letterSpacing: ".1em", textTransform: "uppercase" }}>Resource</Text>
                <Row gap={7} align="center" style={{ marginTop: 3 }}>
                  <Text as="span" style={{ fontSize: 15, color: hueColor(340) }}>{d.glyph}</Text>
                  <Text as="span" weight={600} size={13}>{d.name}</Text>
                </Row>
              </Box>
            )}
            {pos.kind === "external" && (
              <Box style={{ width: "100%", height: "100%", boxSizing: "border-box", padding: "11px 13px", display: "flex", flexDirection: "column", justifyContent: "center",
                borderRadius: 12, background: "color-mix(in oklch, var(--fg) 2%, transparent)",
                border: `1.5px dashed ${isSel ? "var(--accent)" : "var(--border)"}` }}>
                <Text as="span" size={9} tone="muted" style={{ letterSpacing: ".1em", textTransform: "uppercase" }}>External</Text>
                <Row gap={8} align="center" style={{ marginTop: 4 }}>
                  <Box style={{ width: 22, height: 22, borderRadius: "50%", border: "1.5px dashed var(--fg-dim)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 11, color: "var(--fg-muted)" }}>{d.glyph}</Box>
                  <Text as="span" weight={600} size={13}>{d.name}</Text>
                </Row>
              </Box>
            )}
          </div>
        );
      })}
    </>
  );
}

